for i, (prompt, options, answer, explanation, strategy) in enumerate(DATA, 1):
    path = ROOT / "questions/science" / f"question-science-content-na-iv-1-{i}.json"
    item = json.loads(path.read_text())
    target_letters=["A", "B", "C", "D", "B", "C", "D", "A", "C", "B"]
    target=target_letters[i-1]
    correct=options[ord(answer)-65]
    distractors=[t for t in options if t != correct]
    ordered=[]; di=0
    for letter in ["A", "B", "C", "D"]:
        if letter == target: ordered.append(correct)
        else: ordered.append(distractors[di]); di += 1
    item.update({"prompt": prompt, "options": [{"id": chr(65+j), "text": t} for j, t in enumerate(ordered)], "answer": {"value": target, "explanation": f"{explanation} 正確答案為選項 {target}：「{correct}」。"}, "solutionStrategy": strategy, "solutionSteps": ["圈出生物資源、利用方式、補充速率、相互依存關係與可量化結果。", "檢查是否有資源收支、對照、長期監測與不同利害關係人的資料。", f"套用本題原理：{explanation}", f"排除只看短期產量、忽略生態服務或把局部改善當永續的選項，答案為「{correct}」。", "回查結論是否符合承載力、恢復時間與管理邊界。"], "examPatternRefs": REFS, "reviewStatus": "draft"})
    path.write_text(json.dumps(item, ensure_ascii=False, indent=2) + "\n")
print(f"rewrote {len(DATA)} questions")
